// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SampleVault
 * @notice A simple vault for depositing and withdrawing ERC-20 tokens
 * @dev This is a FIXTURE for testing - not a real deployed contract
 */
contract SampleVault is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable token;
    mapping(address => uint256) public balances;
    uint256 public totalDeposited;
    uint256 public feeRate; // basis points (1 = 0.01%)
    address public feeRecipient;

    event Deposit(address indexed user, uint256 amount, uint256 shares);
    event Withdraw(address indexed user, uint256 amount);
    event FeeCollected(address indexed recipient, uint256 amount);

    constructor(address _token, uint256 _feeRate, address _feeRecipient) {
        token = IERC20(_token);
        feeRate = _feeRate;
        feeRecipient = _feeRecipient;
    }

    function deposit(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");

        uint256 fee = (amount * feeRate) / 10000;
        uint256 netAmount = amount - fee;

        token.safeTransferFrom(msg.sender, address(this), amount);

        if (fee > 0) {
            token.safeTransfer(feeRecipient, fee);
            emit FeeCollected(feeRecipient, fee);
        }

        balances[msg.sender] += netAmount;
        totalDeposited += netAmount;

        emit Deposit(msg.sender, netAmount, netAmount);
    }

    function withdraw(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(balances[msg.sender] >= amount, "Insufficient balance");

        balances[msg.sender] -= amount;
        totalDeposited -= amount;

        token.safeTransfer(msg.sender, amount);

        emit Withdraw(msg.sender, amount);
    }

    function setFeeRate(uint256 _feeRate) external onlyOwner {
        require(_feeRate <= 1000, "Fee too high"); // max 10%
        feeRate = _feeRate;
    }

    function setFeeRecipient(address _feeRecipient) external onlyOwner {
        require(_feeRecipient != address(0), "Invalid address");
        feeRecipient = _feeRecipient;
    }
}
